WITH valid_web_events AS (SELECT *, UPPER(page) AS page_upper FROM web_events WHERE TO_DATE(event_time) >= '2025-01-21' AND page = '/home' AND page IN ('/home', '/product', '/cart')), web_events_stats AS (SELECT TO_DATE(event_time) AS event_day, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range FROM valid_web_events GROUP BY TO_DATE(event_time)) SELECT * FROM web_events_stats WHERE duration_sec_range > 51;
